#nullable enable

using System;

namespace Trigger.Models;

public partial class WebhookEndpoint
{
    public string Id { get; set; } = null!;

    public string FriendlyId { get; set; } = null!;

    /// <summary>
    /// URL key. CSPRNG, NOT a friendlyId: crypto.randomBytes(16) base64url.
    /// Generated by the create path (deploy-sync / P2 API), NOT by @default.
    /// </summary>
    public string OpaqueId { get; set; } = null!;

    public string OrganizationId { get; set; } = null!;

    public string ProjectId { get; set; } = null!;

    public string RuntimeEnvironmentId { get; set; } = null!;

    public RuntimeEnvironmentType EnvironmentType { get; set; }

    public string EndpointTenantId { get; set; } = "";

    public string EndpointExternalRef { get; set; } = "";

    public string Source { get; set; } = null!;

    /// <summary>
    /// The declared webhooks.endpoint.define id (string ref, no relation).
    /// </summary>
    public string DeclaredId { get; set; } = null!;

    /// <summary>
    /// Subscribers of this endpoint: StoredWebhookRoutingTarget[] ({ id, type: "task" | "session", ..., filterAst }).
    /// </summary>
    public string RoutingTargets { get; set; } = "[]";

    public string VerifierArtifact { get; set; } = null!;

    public string Metadata { get; set; } = "{}";

    public string SecretProvisioning { get; set; } = "either";

    /// <summary>
    /// The source's instructions for an AI agent registering this endpoint with the provider.
    /// </summary>
    public string? SetupPrompt { get; set; }

    /// <summary>
    /// SecretReference.key string. Plain String, NO @relation -&gt; no FK to SecretReference.
    /// </summary>
    public string? SigningSecretKey { get; set; }

    public WebhookEndpointStatus Status { get; set; } = WebhookEndpointStatus.Active;

    /// <summary>
    /// When an operator disabled the endpoint via the dashboard/API. Null means the declarative sync
    /// owns the status: a redeploy that re-declares a previously-removed (auto-deactivated) webhook
    /// reactivates it. Non-null means the operator disabled it, so the sync leaves the status alone.
    /// </summary>
    public DateTime? ManuallyDeactivatedAt { get; set; }

    public DateTime CreatedAt { get; set; }

    public DateTime UpdatedAt { get; set; }
}
